/* Pan Tech Africa visual skin: photo hero + category tiles. Load AFTER the main script. */
(function(){
const J=d=>'data:image/jpeg;base64,'+d;
const IMG={hero:J(""),0:J(""),1:J(""),2:J(""),3:J(""),4:J(""),5:J(""),6:J(""),7:J("")};
const g=(b)=>'<svg viewBox="0 0 52 52" width="54" height="54">'+b+'</svg>';
const ICO={
1:g('<rect x="9" y="12" width="34" height="23" rx="3" fill="#33455f"/><rect x="12" y="15" width="28" height="17" rx="1" fill="#19b8a6"/><path d="M4 38h44l-3 5H7z" fill="#9aa6ba"/>'),
2:g('<rect x="9" y="7" width="34" height="38" rx="6" fill="#33455f"/><rect x="12" y="11" width="28" height="30" rx="2" fill="#19b8a6"/>'),
3:g('<rect x="19" y="3" width="14" height="46" rx="5" fill="#6b7788"/><rect x="13" y="15" width="26" height="22" rx="8" fill="#33455f"/><rect x="16" y="18" width="20" height="16" rx="5" fill="#19b8a6"/>'),
6:g('<rect x="12" y="8" width="28" height="38" rx="7" fill="#33455f"/><rect x="17" y="14" width="18" height="6" rx="2" fill="#19b8a6"/><rect x="17" y="24" width="18" height="3" rx="1.5" fill="#ffffff66"/><rect x="17" y="31" width="12" height="3" rx="1.5" fill="#ffffff66"/>'),
7:g('<rect x="4" y="16" width="44" height="22" rx="4" fill="#33455f"/><g fill="#9aa6ba"><rect x="9" y="21" width="6" height="4" rx="1"/><rect x="18" y="21" width="6" height="4" rx="1"/><rect x="27" y="21" width="6" height="4" rx="1"/><rect x="36" y="21" width="6" height="4" rx="1"/><rect x="14" y="29" width="24" height="4" rx="1"/></g>'),
8:g('<rect x="8" y="8" width="16" height="16" rx="4" fill="#19b8a6"/><rect x="28" y="8" width="16" height="16" rx="4" fill="#33455f"/><rect x="8" y="28" width="16" height="16" rx="4" fill="#33455f"/><rect x="28" y="28" width="16" height="16" rx="4" fill="#9aa6ba"/>')};
const css=document.createElement('style');
css.textContent=`.hero2{position:relative;border-radius:26px;overflow:hidden;margin-bottom:6px}.hero2 img{display:block;width:100%;height:auto;min-height:190px;object-fit:cover}
.hero2 .cap{position:absolute;inset:auto 0 0 0;padding:44px 16px 14px;color:#fff;background:linear-gradient(transparent,#061a30e6)}
.hero2 h2{margin:0;font-size:21px;line-height:1.2}.hero2 p{margin:4px 0 10px;font-size:13px}
.rowh{display:flex;justify-content:space-between;align-items:baseline}.rowh a{font-weight:600;cursor:pointer}
.cats2{display:flex;gap:14px;overflow-x:auto;padding:10px 2px 8px;scrollbar-width:none}.cats2::-webkit-scrollbar{display:none}
.ct{flex:0 0 84px;text-align:center;font-size:12px;line-height:1.25;cursor:pointer}
.ct .tl{width:84px;height:84px;border-radius:24px;overflow:hidden;display:grid;place-items:center;margin-bottom:6px;background:#eceff3}
.ct .tl img{width:100%;height:100%;object-fit:cover}`;
document.head.appendChild(css);
const old=V.home;
V.home=function(){
 const h=old(),i=h.search(/<h2[^>]*>Featured/);
 if(i<0)return h;
 const top=`<div class="hero2"><img src="${IMG.hero}" alt="Phones and gadgets"><div class="cap"><h2>Latest Smartphones,<br>Laptops &amp; <span style="color:#19d8c3">Gadgets</span></h2><p>Compare specs, find great deals and pay with Pi.</p><div class="row"><button style="background:#19d8c3;color:#06223a;font-weight:700;border-radius:22px" onclick="go('shop')">Shop Now &rarr;</button><button style="background:transparent;color:#fff;border:1px solid #ffffffaa;border-radius:22px" onclick="go('compare')">Compare Products</button></div></div></div>
 <div class="rowh"><h2>Categories</h2><a onclick="go('shop')">See all</a></div>
 <div class="cats2">${CATS.map((c,k)=>`<div class="ct" onclick="flt.cat=${k};go2()"><div class="tl">${IMG[k]?`<img src="${IMG[k]}" alt="">`:ICO[k]}</div>${c[0]}</div>`).join('')}</div>`;
 return top+h.slice(i);
};

/* Product photos on cards and detail view, matched by product name */
const NEW={iphone:J(""),tecno:J(""),redmi:J(""),hp:J(""),mac:J(""),mouse:J("")};
const MAP=[["galaxy a55",IMG[0]],["iphone",NEW.iphone],["camon",NEW.tecno],["redmi note",NEW.redmi],["thinkpad",IMG[1]],["hp 255",NEW.hp],["macbook",NEW.mac],["tab a9",IMG[2]],["watch",IMG[3]],["buds",IMG[4]],["charger",IMG[5]],["powercore",IMG[6]],["power bank",IMG[6]],["mx keys",IMG[7]],["keyboard",IMG[7]],["mouse",NEW.mouse]];
const photoFor=p=>{const n=String(p.name||'').toLowerCase();for(const m of MAP)if(n.includes(m[0]))return m[1];return ''};
const st2=document.createElement('style');
st2.textContent='.img:has(img){background:#eceff3!important;height:130px!important}.img img{object-fit:contain!important}';
document.head.appendChild(st2);
const oc=card;card=function(p){if(!p.img){const u=photoFor(p);if(u)p=Object.assign({},p,{img:u})}return oc(p)};
const od=detail;detail=function(id){od(id);const p=pc(id),u=photoFor(p);if(u&&!(p.imgs&&p.imgs.length)){const d=document.querySelector('.modal .img');if(d){d.style.fontSize='0';d.style.background='#eceff3';d.innerHTML='<img alt="" src="'+u+'" style="height:100%;object-fit:contain">'}}};
render();
})();
